-- Hosbah (MH-580 J5): a Trivy `image` scan of one app's current release image, run in a container on
-- the app's own server (agent op app.scan — see agentproto.KindAppScan) and reported back as a
-- compact summary: counts by severity plus the top findings (bounded, see
-- agentproto.MaxScanFindings; truncated notes when more existed). triggered_by is 'member' (the
-- "Scan now" button), 'mcp' (the app_scan MCP tool) or 'deploy' (the best-effort, non-blocking scan
-- internal/deploy kicks off after a release goes live). Rows go with their team; every write is a
-- team-scope member action (owner/admin/deployer) or the deploy pipeline's own team-scoped write —
-- never system scope, like server_update_statuses.
ALTER TABLE app_scans ADD CONSTRAINT app_scans_status_check CHECK (status IN ('running', 'ok', 'failed'));
ALTER TABLE app_scans ADD CONSTRAINT app_scans_triggered_by_check CHECK (triggered_by IN ('member', 'mcp', 'deploy'));
ALTER TABLE app_scans ADD CONSTRAINT app_scans_findings_check CHECK (jsonb_typeof(findings) = 'array');
CREATE INDEX app_scans_app_idx ON app_scans (app_id, created_at DESC);
CREATE INDEX app_scans_team_idx ON app_scans (team_id, created_at DESC);
